//! 🎞️ Writes named timelines, target properties, interpolation and every exact keyframe variant.
use crate::standards::v1::subsets::animation::schema::snapshot::{SemioAnimationSnapshot,AnimTimeline,AnimChannel,AnimTarget,AnimTargetProperty,AnimInterpolation,AnimKeyframe,AnimValue};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_encoding::{self,Writer};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl,ValueError};
pub(crate) fn encode(snapshot:&SemioAnimationSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io::IoPayload,ValueError>{native_encoding::encode_admitted(encoding,"semio s.stdio.semio.animation.dsl v1\n","s.stdio.semio.animation.pack v1",control,|control|crate::standards::v1::subsets::animation::io::sqlite::snapshot::admit_values(snapshot,store::sqlite_snapshot::SqliteSnapshotPhase::EncodeNative,control),|writer,encoding|fields(snapshot,writer,encoding))}
fn target(target:&AnimTarget,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&target.node,encoding)?;writer.delimiter(b",",encoding)?;let(binary,text)=match target.property{AnimTargetProperty::Translation=>(0,b't'),AnimTargetProperty::Rotation=>(1,b'r'),AnimTargetProperty::Scale=>(2,b's'),AnimTargetProperty::Weights=>(3,b'w'),AnimTargetProperty::Custom{..}=>(4,b'c')};writer.byte(if encoding==SnapshotEncoding::Binary{binary}else{text})?;if let AnimTargetProperty::Custom{name}=&target.property{writer.delimiter(b":",encoding)?;writer.string(name,encoding)?;}writer.delimiter(b"]",encoding)}
fn value(value:&AnimValue,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{let(binary,text)=match value{AnimValue::Scalar{..}=>(0,b'S'),AnimValue::Vec3{..}=>(1,b'V'),AnimValue::Quat{..}=>(2,b'Q'),AnimValue::Weights{..}=>(3,b'W')};writer.byte(if encoding==SnapshotEncoding::Binary{binary}else{text})?;writer.delimiter(b":",encoding)?;match value{
 AnimValue::Scalar{value}=>writer.number(*value,encoding),
 AnimValue::Vec3{value}=>{writer.delimiter(b"[",encoding)?;writer.number(value.x,encoding)?;writer.delimiter(b",",encoding)?;writer.number(value.y,encoding)?;writer.delimiter(b",",encoding)?;writer.number(value.z,encoding)?;writer.delimiter(b"]",encoding)},
 AnimValue::Quat{value}=>{writer.delimiter(b"[",encoding)?;for(index,value)in [value.x,value.y,value.z,value.w].into_iter().enumerate(){if index!=0{writer.delimiter(b",",encoding)?;}writer.number(value,encoding)?;}writer.delimiter(b"]",encoding)},
 AnimValue::Weights{values}=>writer.list(values,encoding,|writer,value|writer.number(*value,encoding))}}
fn keyframe(keyframe:&AnimKeyframe,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.delimiter(b"[",encoding)?;writer.number(keyframe.t,encoding)?;writer.delimiter(b",",encoding)?;value(&keyframe.value,writer,encoding)?;writer.delimiter(b"]",encoding)}
fn channel(channel:&AnimChannel,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.delimiter(b"[",encoding)?;target(&channel.target,writer,encoding)?;writer.delimiter(b",",encoding)?;writer.byte(match(channel.interpolation,encoding){(AnimInterpolation::Linear,SnapshotEncoding::Binary)=>0,(AnimInterpolation::Step,SnapshotEncoding::Binary)=>1,(AnimInterpolation::CubicSpline,SnapshotEncoding::Binary)=>2,(AnimInterpolation::Linear,SnapshotEncoding::Text)=>b'l',(AnimInterpolation::Step,SnapshotEncoding::Text)=>b's',(AnimInterpolation::CubicSpline,SnapshotEncoding::Text)=>b'c'})?;writer.delimiter(b",",encoding)?;writer.list(&channel.keyframes,encoding,|writer,value|keyframe(value,writer,encoding))?;writer.delimiter(b"]",encoding)}
fn timeline(timeline:&AnimTimeline,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.delimiter(b"[",encoding)?;match &timeline.name{Some(name)=>{if encoding==SnapshotEncoding::Binary{writer.byte(1)?}else{writer.bytes(b"[1,")?}writer.string(name,encoding)?;writer.delimiter(b"]",encoding)?},None=>if encoding==SnapshotEncoding::Binary{writer.byte(0)?}else{writer.bytes(b"[0]")?}}writer.delimiter(b",",encoding)?;writer.list(&timeline.channels,encoding,|writer,value|channel(value,writer,encoding))?;writer.delimiter(b"]",encoding)}
pub(crate) fn fields(snapshot:&SemioAnimationSnapshot,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.entities(1)?;if encoding==SnapshotEncoding::Binary{writer.byte(1)?}else{writer.bytes(b"schema=")?}writer.string(&snapshot.schema,encoding)?;writer.delimiter(b"\ntimelines=",encoding)?;writer.list(&snapshot.timelines,encoding,|writer,value|timeline(value,writer,encoding))}
